490	    /**
491	     * The late fee in the invoice's currency: the fee in US dollars converted as a payment in another
492	     * currency is, through the workspace rate, rounded half up to the currency's step.
493	     */
494	    private BigDecimal lateFeeIn(BigDecimal feeUsd) {
495	        if (currency() == Currency.USD) {
496	            return feeUsd.setScale(scale(), RoundingMode.HALF_UP);
497	        }
498	        BigDecimal rate = usdPer == null ? BigDecimal.ONE : new BigDecimal(usdPer.trim());
499	        return currency().roundToStep(feeUsd.divide(rate, MathContext.DECIMAL128));
