502	    /**
503	     * Works out the late fee and late interest charged by the given day, at the late fee (in US
504	     * dollars) and annual rate (a percentage), from the payments (those not reversed count), and keeps
505	     * them as part of what is payable. The fee is charged once, on the day the invoice becomes overdue
506	     * ({@link #GRACE_DAYS} days after its due date), when something is still owed then; it earns no
507	     * interest, and a payment from then on pays it first. A sent invoice not
508	     * spread over instalments, with something still owed more than {@link #GRACE_DAYS} days after its
509	     * due date, earns interest from the end of its grace week ({@link #GRACE_DAYS} days after its due
510	     * date), compounded daily at rate / 365: a balance B owing for
511	     * d days earns B x ((1 + rate / 100 / 365)^d - 1), rounded half up to the cent. Each payment after
512	     * the grace week ends a period; every period earns interest on what the invoice still owed during it
513	     * (earlier interest, the fee and retention left out), and a payment pays the fee, then the interest
514	     * earned so far, then the invoice. An invoice spread over instalments instead earns interest
515	     * instalment by instalment (see {@link #accrueInstalmentInterest}), and no late fee. On the day the
516	     * charges were waived (after the day's payments), the fee and interest still unpaid are written off
517	     * (kept as what was waived) and that day ends a period: interest starts again from it on what is
518	     * still owed, and no new fee is charged.
519	     */
520	    public void accrueLateInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
521	            BigDecimal lateFeeUsd, LocalDate today) {
522	        this.lateInterest = BigDecimal.ZERO;
523	        this.lateFee = BigDecimal.ZERO;
524	        this.lateWaived = BigDecimal.ZERO;
525	        this.instalmentInterest = List.of();
526	        if (status == InvoiceStatus.SENT && !isCreditNote() && hasPlan()) {
527	            accrueInstalmentInterest(payments, taxRate, annualRate, today);
528	            return;
529	        }
530	        if (status != InvoiceStatus.SENT || isCreditNote() || hasPlan() || dueDate == null
531	                || !today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
532	            return;
533	        }
534	        boolean earnsInterest = annualRate != null && annualRate.signum() > 0;
535	        BigDecimal fee = lateFeeUsd == null || lateFeeUsd.signum() <= 0 ? zero() : lateFeeIn(lateFeeUsd);
536	        if (!earnsInterest && fee.signum() <= 0) {
537	            return;
538	        }
539	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
540	        }
541	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
542	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
543	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
544	                .filter(p -> !p.on().isAfter(today))
545	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
546	        BigDecimal owed = payableBeforeInterest(taxRate).subtract(retentionReleased(taxRate));
547	        BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(dueDate.plusDays(GRACE_DAYS)))
548	                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
549	        if (owed.subtract(paidInGrace).signum() <= 0) {
550	            return;
551	        }
552	        BigDecimal daily = earnsInterest
553	                ? BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36500), MathContext.DECIMAL128))
554	                : null;
555	        LocalDate overdueOn = dueDate.plusDays(GRACE_DAYS + 1);
556	        BigDecimal charged = BigDecimal.ZERO;
557	        BigDecimal unpaidInterest = BigDecimal.ZERO;
558	        BigDecimal unpaidFee = BigDecimal.ZERO;
559	        boolean feeCharged = false;
560	        LocalDate from = dueDate.plusDays(GRACE_DAYS);
561	        LocalDate waiveOn = interestWaivedOn != null && !interestWaivedOn.isBefore(overdueOn)
562	                && !interestWaivedOn.isAfter(today) ? interestWaivedOn : null;
563	        BigDecimal feeWaived = BigDecimal.ZERO;
564	        BigDecimal interestWaived = BigDecimal.ZERO;
565	        for (Part part : inOrder) {
566	            if (waiveOn != null && part.on().isAfter(waiveOn)) {
567	                if (!feeCharged) {
568	                    unpaidFee = fee;
569	                    feeCharged = true;
570	                }
571	                if (earnsInterest && owed.signum() > 0) {
572	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
573	                    charged = charged.add(earned);
574	                    unpaidInterest = unpaidInterest.add(earned);
575	                }
576	                from = waiveOn;
577	                feeWaived = unpaidFee;
578	                interestWaived = unpaidInterest;
579	                unpaidFee = BigDecimal.ZERO;
580	                unpaidInterest = BigDecimal.ZERO;
581	                waiveOn = null;
582	            }
583	            if (!feeCharged && !part.on().isBefore(overdueOn)) {
584	                unpaidFee = fee;
585	                feeCharged = true;
586	            }
587	            BigDecimal toFee = part.amount().min(unpaidFee).max(BigDecimal.ZERO);
588	            unpaidFee = unpaidFee.subtract(toFee);
589	            BigDecimal rest = part.amount().subtract(toFee);
590	            if (earnsInterest && part.on().isAfter(from) && owed.signum() > 0) {
591	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
592	                charged = charged.add(earned);
593	                unpaidInterest = unpaidInterest.add(earned);
594	                from = part.on();
595	            }
596	            BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
597	            unpaidInterest = unpaidInterest.subtract(toInterest);
598	            owed = owed.subtract(rest.subtract(toInterest));
599	        }
600	        if (waiveOn != null) {
601	            if (earnsInterest && owed.signum() > 0) {
602	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
603	                charged = charged.add(earned);
604	                unpaidInterest = unpaidInterest.add(earned);
605	            }
606	            from = waiveOn;
607	            feeWaived = feeCharged ? unpaidFee : fee;
608	            interestWaived = unpaidInterest;
609	        }
610	        if (earnsInterest && owed.signum() > 0) {
611	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
612	        }
613	        this.lateFee = fee.subtract(feeWaived);
614	        this.lateInterest = charged.subtract(interestWaived);
615	        this.lateWaived = feeWaived.add(interestWaived);
616	    }
617	
618	    /**
619	     * Works out the late interest each instalment of the plan has been charged by the given day, at the
620	     * annual rate (a percentage), from the payments (those not reversed count; what credit notes took
621	     * off counts from the issue date). Payments, in the order they were made, pay each instalment's
622	     * interest earned so far and then the instalment itself, earliest instalment first. An instalment
623	     * still not paid off more than {@link #GRACE_DAYS} days after its due date earns interest by the
624	     * same rule as an invoice: from the end of its own grace week, compounded daily at rate / 365, on
625	     * what is still unpaid of it, with each payment after its grace week ending a period.
626	     */
627	    private void accrueInstalmentInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
628	            LocalDate today) {
629	        if (annualRate == null || annualRate.signum() <= 0) {
630	            return;
631	        }
632	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
633	        }
634	        List<Part> inOrder = new ArrayList<>();
635	        if (getCredited().signum() > 0) {
636	            inOrder.add(new Part(issueDate == null ? LocalDate.MIN : issueDate, 0L, getCredited()));
637	        }
638	        payments.stream().filter(p -> !p.isReversed())
639	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
640	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
641	                .filter(p -> !p.on().isAfter(today))
642	                .forEach(inOrder::add);
643	        inOrder.sort(Comparator.comparing(Part::on).thenComparing(Part::paymentId));
644	        if (getInterestSaved().signum() > 0 && !inOrder.isEmpty()) {
645	            // The interest dropped by paying the plan off counts as paid with the payment that settled it.
646	            inOrder.add(new Part(inOrder.get(inOrder.size() - 1).on(), Long.MAX_VALUE, getInterestSaved()));
647	        }
648	        BigDecimal[] left = inOrder.stream().map(Part::amount).toArray(BigDecimal[]::new);
649	        BigDecimal daily = BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36500), MathContext.DECIMAL128));
650	        List<BigDecimal> charges = new ArrayList<>();
651	        BigDecimal total = BigDecimal.ZERO;
652	        for (Instalment instalment : schedule(taxRate)) {
653	            LocalDate due = instalment.dueDate();
654	            BigDecimal owed = instalment.payment();
655	            boolean late = false;
656	            if (due != null && today.isAfter(due.plusDays(GRACE_DAYS))) {
657	                BigDecimal paidInGrace = BigDecimal.ZERO;
658	                for (int j = 0; j < left.length; j++) {
659	                    if (!inOrder.get(j).on().isAfter(due.plusDays(GRACE_DAYS))) {
660	                        paidInGrace = paidInGrace.add(left[j]);
661	                    }
662	                }
663	                late = paidInGrace.compareTo(owed) < 0;
664	            }
665	            BigDecimal charged = BigDecimal.ZERO;
666	            BigDecimal unpaidInterest = BigDecimal.ZERO;
667	            LocalDate from = due == null ? null : due.plusDays(GRACE_DAYS);
668	            for (int j = 0; j < left.length; j++) {
669	                Part part = inOrder.get(j);
670	                if (late && part.on().isAfter(from) && owed.signum() > 0) {
671	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
672	                    charged = charged.add(earned);
673	                    unpaidInterest = unpaidInterest.add(earned);
674	                    from = part.on();
675	                }
676	                BigDecimal toInterest = left[j].min(unpaidInterest).max(BigDecimal.ZERO);
677	                unpaidInterest = unpaidInterest.subtract(toInterest);
678	                BigDecimal toOwed = left[j].subtract(toInterest).min(owed).max(BigDecimal.ZERO);
679	                owed = owed.subtract(toOwed);
680	                left[j] = left[j].subtract(toInterest).subtract(toOwed);
681	            }
682	            if (late && owed.signum() > 0) {
683	                charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
684	            }
685	            charges.add(charged.setScale(scale(), RoundingMode.HALF_UP));
686	            total = total.add(charged);
687	        }
688	        this.instalmentInterest = charges;
689	        this.lateInterest = total;
690	    }
691	
692	    /** The interest the balance earns over the days at the daily growth factor, rounded half up to the cent. */
693	    private BigDecimal interestOn(BigDecimal balance, BigDecimal daily, long days) {
694	        if (days <= 0) {
695	            return zero();
696	        }
697	        return balance.multiply(daily.pow((int) days, MathContext.DECIMAL128).subtract(BigDecimal.ONE))
698	                .setScale(scale(), RoundingMode.HALF_UP);
699	    }
