701	    /**
702	     * The early-payment discount on offer at the tax rate: the client's early-payment percentage of the
703	     * grand total, rounded down to the cent; nothing for a credit note, or an invoice holding back
704	     * retention or spread over instalments.
705	     */
706	    public BigDecimal earlyDiscount(BigDecimal taxRate) {
707	        if (isCreditNote() || hasPlan() || retentionPct.signum() > 0 || earlyPayDays == null
708	                || earlyPayPct == null || earlyPayPct.signum() <= 0) {
709	            return zero();
710	        }
711	        return total(taxRate).multiply(earlyPayPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
712	    }
