714	    /**
715	     * Whether a sent invoice not yet settled early can still be paid off early on the given day: within
716	     * the client's early-payment days of its issue date, with an early discount on offer.
717	     */
718	    public boolean isEarlyWindowOpen(LocalDate on, BigDecimal taxRate) {
719	        return status == InvoiceStatus.SENT && issueDate != null && getEarlyDiscountTaken().signum() == 0
720	                && earlyDiscount(taxRate).signum() > 0 && !on.isAfter(issueDate.plusDays(earlyPayDays));
721	    }
