723	    /**
724	     * What would settle the invoice on the given day once the given amount has been paid: what is due
725	     * less the early discount while the early window is open; null when it is not.
726	     */
727	    public BigDecimal settleAmount(BigDecimal paid, BigDecimal taxRate, LocalDate on) {
728	        BigDecimal due = amountDue(paid, taxRate);
729	        if (!isEarlyWindowOpen(on, taxRate) || due.signum() <= 0) {
730	            return null;
731	        }
732	        return due.subtract(earlyDiscount(taxRate)).max(zero());
733	    }
