755	    /**
756	     * What would pay off a sent plan not yet paid off on the given day, once the given amount has been
757	     * paid, at the tax rate: the principal still owed on all its instalments, plus what is unpaid of
758	     * the interest of the instalments already due (due on or before the day) and any late interest.
759	     * Within an instalment what is paid goes to its interest first. Null without a plan, or when
760	     * nothing is due.
761	     */
762	    public BigDecimal payoff(BigDecimal paid, BigDecimal taxRate, LocalDate on) {
763	        if (!hasPlan() || status != InvoiceStatus.SENT || isCreditNote() || getInterestSaved().signum() > 0
764	                || amountDue(paid, taxRate).signum() <= 0) {
765	            return null;
766	        }
767	        BigDecimal payoff = zero();
768	        for (Instalment.Progress p : instalmentProgress(paid, taxRate, on)) {
769	            LocalDate due = p.instalment().dueDate();
770	            BigDecimal unpaid = due == null || !due.isAfter(on) ? p.unpaid() : p.unpaid().min(p.instalment().principal());
771	            payoff = payoff.add(unpaid).add(p.interestUnpaid());
772	        }
773	        return payoff;
774	    }
