797	    /**
798	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
799	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
800	     * i)^-n), or P / n at 0%, rounded half up to the cent. Each month's interest is the balance still
801	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
802	     * last instalment pays off the whole balance left plus its interest, so the schedule ends at zero.
803	     * Instalment k falls due k months after the issue date, on the same day (the month's last day when
804	     * it is shorter).
805	     */
806	    public List<Instalment> schedule(BigDecimal taxRate) {
807	        if (!hasPlan()) {
808	            return List.of();
809	        }
810	        MathContext mc = MathContext.DECIMAL128;
811	        BigDecimal principal = total(taxRate);
812	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
813	        int n = instalments;
814	        BigDecimal payment;
815	        if (i.signum() == 0) {
816	            payment = principal.divide(BigDecimal.valueOf(n), scale(), RoundingMode.HALF_UP);
817	        } else {
818	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
819	            payment = principal.multiply(i).multiply(growth)
820	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(scale(), RoundingMode.HALF_UP);
821	        }
822	        List<Instalment> schedule = new ArrayList<>(n);
823	        BigDecimal balance = principal.setScale(scale(), RoundingMode.HALF_UP);
824	        for (int k = 1; k <= n; k++) {
825	            BigDecimal interest = balance.multiply(i).setScale(scale(), RoundingMode.HALF_UP);
826	            BigDecimal paid = k == n ? balance.add(interest) : payment;
827	            BigDecimal repaid = paid.subtract(interest);
828	            balance = balance.subtract(repaid);
829	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
830	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
831	        }
832	        return schedule;
833	    }
