843	    /**
844	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
845	     * day: payments (with what credit notes took off and anything written off) pay the instalments in
846	     * order, each its late interest and then itself, each paid off before the next. An instalment not
847	     * paid off more than {@link #GRACE_DAYS} days after its due date is overdue; empty when there is no
848	     * plan.
849	     */
850	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
851	        List<Instalment.Progress> progress = new ArrayList<>();
852	        BigDecimal left = paid.add(getCredited()).add(writtenOff(paid, taxRate)).add(getInterestSaved());
853	        List<Instalment> schedule = schedule(taxRate);
854	        for (int k = 0; k < schedule.size(); k++) {
855	            Instalment instalment = schedule.get(k);
856	            BigDecimal interest = k < instalmentInterest.size() ? instalmentInterest.get(k) : zero();
857	            BigDecimal toInterest = left.min(interest).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
858	            left = left.subtract(toInterest);
859	            BigDecimal interestUnpaid = interest.subtract(toInterest);
860	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
861	            left = left.subtract(part);
862	            BigDecimal unpaid = instalment.payment().subtract(part);
863	            Instalment.Status status;
864	            if (unpaid.signum() <= 0 && interestUnpaid.signum() <= 0) {
865	                status = Instalment.Status.PAID;
866	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(GRACE_DAYS))) {
867	                status = Instalment.Status.OVERDUE;
868	            } else if (part.signum() > 0) {
869	                status = Instalment.Status.PART_PAID;
870	            } else {
871	                status = Instalment.Status.DUE;
872	            }
873	            progress.add(new Instalment.Progress(instalment, part, unpaid, interest, interestUnpaid, status));
874	        }
875	        return progress;
876	    }
