878	    /**
879	     * What is overdue at the tax rate once the given amount has been paid, on the given day: for a plan,
880	     * only what is unpaid on its overdue instalments, their late interest included; otherwise all that is due when it is overdue.
881	     */
882	    public BigDecimal overdueAmount(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
883	        if (statusWhenPaid(paid, taxRate, today) != InvoiceStatus.OVERDUE) {
884	            return zero();
885	        }
