993	    }
994	
995	    /**
996	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
997	     * paid date (null when not known) is after its due date is paid late.
998	     */
999	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
1000	        if (status != InvoiceStatus.SENT) {
1001	            return status;
1002	        }
1003	        BigDecimal amountDue = amountDue(paid, taxRate);
1004	        boolean due = amountDue.signum() > 0;
1005	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
1006	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
1007	        if (hasPlan()) {
1008	            if (due && instalmentProgress(paid, taxRate, today).stream()
1009	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
1010	                return InvoiceStatus.OVERDUE;
1011	            }
1012	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
1013	            return InvoiceStatus.OVERDUE;
1014	        }
1015	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
1016	            return InvoiceStatus.OVERDUE;
1017	        }
1018	        if (!due && retentionHeld(taxRate).signum() > 0) {
1019	            return InvoiceStatus.RETENTION_HELD;
1020	        }
1021	        if (paid.signum() <= 0) {
1022	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
1023	        }
1024	        if (due) {
1025	            return InvoiceStatus.PART_PAID;
1026	        }
1027	        LocalDate finalDue = hasPlan() ? schedule(taxRate).get(instalments - 1).dueDate() : dueDate;
1028	        return paidOn != null && finalDue != null && paidOn.isAfter(finalDue) ? InvoiceStatus.PAID_LATE
1029	                : InvoiceStatus.PAID;
1030	    }
