1032	    /**
1033	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
1034	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
1035	     * counts on the day it was applied); null while something is still due or retention is held.
1036	     */
1037	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
1038	        BigDecimal total = payable(taxRate);
1039	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
1040	            return null;
1041	        }
1042	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
1043	        }
1044	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
1045	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
1046	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
1047	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
1048	        BigDecimal sum = BigDecimal.ZERO;
1049	        for (Part p : inOrder) {
1050	            sum = sum.add(p.amount());
1051	            if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum))) {
1052	                return p.on();
1053	            }
1054	        }
1055	        return null;
1056	    }
