1058	    /**
1059	     * What is still due once the given amount has been paid: the grand total less it, less what credit
1060	     * notes have credited, less the retention still held, less anything written off — so nothing once
1061	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
1062	     */
1063	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
1064	        if (isCreditNote()) {
1065	            return zero();
1066	        }
1067	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
1068	    }
1069	
1070	    /**
1071	     * What is written off once the given amount has been paid: when payments leave less than
1072	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
1073	     */
1074	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
1075	        BigDecimal left = payable(taxRate).subtract(paid);
1076	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && isSmallEnoughToWriteOff(left)
1077	                ? left.setScale(scale(), RoundingMode.HALF_UP)
1078	                : zero();
1079	    }
