1086	    /**
1087	     * Whether paying the amount on top of what was already paid is too small a part payment: under
1088	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
1089	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
1090	     */
1091	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
1092	        if (hasPlan()) {
1093	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
1094	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
1095	        }
1096	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
1097	    }
