1149	    /**
1150	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
1151	     * matches what a client gets by adding up the lines shown.
1152	     */
1153	    public BigDecimal subtotal() {
1154	        return lines.stream().map(l -> l.amount(scale()))
1155	                .reduce(zero(), BigDecimal::add);
1156	    }
1157	
1158	    /**
1159	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
1160	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
1161	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
1162	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
1163	     */
1164	    public BigDecimal discount() {
1165	        BigDecimal discount = discountAmount.signum() > 0
1166	                ? discountAmount.min(subtotal()).setScale(scale(), RoundingMode.HALF_UP)
1167	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
1168	        if (discountCap == null) {
1169	            return discount;
1170	        }
1171	        BigDecimal lineDiscounts = lines.stream().map(l -> l.discount(scale()))
1172	                .reduce(zero(), BigDecimal::add);
1173	        BigDecimal left = discountCap.setScale(scale(), RoundingMode.HALF_UP).subtract(lineDiscounts).max(zero());
1174	        return discount.min(left);
1175	    }
