1177	    /**
1178	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
1179	     * proportion to the line amounts: each line first gets the whole cents of its exact share
1180	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
1181	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
1182	     * equal amounts too to the lower line id. The shares add up to the discount.
1183	     */
1184	    public List<BigDecimal> discountShares() {
1185	        BigInteger discountCents = discount().movePointRight(scale()).toBigIntegerExact();
1186	        BigInteger subtotalCents = subtotal().movePointRight(scale()).toBigIntegerExact();
1187	        int n = lines.size();
1188	        BigInteger[] shares = new BigInteger[n];
1189	        BigInteger[] leftovers = new BigInteger[n];
1190	        BigInteger given = BigInteger.ZERO;
1191	        for (int i = 0; i < n; i++) {
1192	            if (subtotalCents.signum() == 0) {
1193	                shares[i] = BigInteger.ZERO;
1194	                leftovers[i] = BigInteger.ZERO;
1195	            } else {
1196	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
1197	                // as denominator, so the remainders compare as the fractions do.
1198	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount(scale()).movePointRight(scale()).toBigIntegerExact())
1199	                        .divideAndRemainder(subtotalCents);
1200	                shares[i] = qr[0];
1201	                leftovers[i] = qr[1];
1202	            }
1203	            given = given.add(shares[i]);
1204	        }
1205	        List<Integer> order = new ArrayList<>();
1206	        for (int i = 0; i < n; i++) {
1207	            order.add(i);
1208	        }
1209	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1210	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount(scale())).reversed())
1211	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1212	        int left = discountCents.subtract(given).intValueExact();
1213	        for (int k = 0; k < left; k++) {
1214	            int i = order.get(k);
1215	            shares[i] = shares[i].add(BigInteger.ONE);
1216	        }
1217	        List<BigDecimal> result = new ArrayList<>(n);
1218	        for (BigInteger share : shares) {
1219	            result.add(new BigDecimal(share, scale()));
1220	        }
1221	        return result;
1222	    }
1223	
1224	    /**
1225	     * Each line's exact tax, in the order of the lines: the line's own rate (a percentage), or the
1226	     * given workspace rate when it has none, on the line's amount less its share of the discount,
1227	     * unrounded. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
1228	     */
1229	    private List<BigDecimal> exactLineTaxes(BigDecimal taxRate) {
1230	        List<BigDecimal> shares = discountShares();
1231	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
1232	        for (int i = 0; i < lines.size(); i++) {
1233	            InvoiceLine line = lines.get(i);
1234	            taxes.add(clientTaxExempt || line.isTaxExempt() ? BigDecimal.ZERO
1235	                    : line.amount(scale()).subtract(shares.get(i)).multiply(line.taxRate(taxRate)).movePointLeft(2));
1236	        }
1237	        return taxes;
1238	    }
1239	
1240	    /**
1241	     * Each line's share of the invoice tax, in the order of the lines. The tax's cents are split in
1242	     * proportion to the lines' exact taxes as the discount is split: each line first gets the whole
1243	     * cents of its exact share (rounded down), then the cents left over go one each to the lines with
1244	     * the largest leftover fractions; between equal fractions the cent goes to the line with the
1245	     * larger exact tax, and between equal exact taxes too to the lower line id. The line taxes add up
1246	     * to the invoice tax.
1247	     */
1248	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
1249	        List<BigDecimal> exact = exactLineTaxes(taxRate);
1250	        int n = lines.size();
1251	        BigInteger taxCents = roundTax(exact).movePointRight(scale()).toBigIntegerExact();
1252	        int common = exact.stream().mapToInt(BigDecimal::scale).max().orElse(0);
1253	        BigInteger[] weights = new BigInteger[n];
1254	        BigInteger total = BigInteger.ZERO;
1255	        for (int i = 0; i < n; i++) {
1256	            weights[i] = exact.get(i).setScale(common).unscaledValue();
1257	            total = total.add(weights[i]);
1258	        }
1259	        if (total.signum() < 0) {
1260	            // Split the magnitude, so the leftover cents are always added, then flip the shares back.
1261	            taxCents = taxCents.negate();
1262	            total = total.negate();
1263	            for (int i = 0; i < n; i++) {
1264	                weights[i] = weights[i].negate();
1265	            }
1266	        }
1267	        BigInteger[] shares = new BigInteger[n];
1268	        BigInteger[] leftovers = new BigInteger[n];
1269	        BigInteger given = BigInteger.ZERO;
1270	        for (int i = 0; i < n; i++) {
1271	            if (total.signum() == 0) {
1272	                shares[i] = BigInteger.ZERO;
1273	                leftovers[i] = BigInteger.ZERO;
1274	            } else {
1275	                // The exact share is tax * exact line tax / total exact tax; all fractions share the
1276	                // total as denominator, so the remainders compare as the fractions do.
1277	                BigInteger[] qr = taxCents.multiply(weights[i]).divideAndRemainder(total);
1278	                if (qr[1].signum() < 0) {
1279	                    qr[0] = qr[0].subtract(BigInteger.ONE);
1280	                    qr[1] = qr[1].add(total);
1281	                }
1282	                shares[i] = qr[0];
1283	                leftovers[i] = qr[1];
1284	            }
1285	            given = given.add(shares[i]);
1286	        }
1287	        List<Integer> order = new ArrayList<>();
1288	        for (int i = 0; i < n; i++) {
1289	            order.add(i);
1290	        }
1291	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1292	                .thenComparing(Comparator.<Integer, BigInteger>comparing(i -> weights[i]).reversed())
1293	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1294	        int left = taxCents.subtract(given).intValueExact();
1295	        for (int k = 0; k < left; k++) {
1296	            int i = order.get(k);
1297	            shares[i] = shares[i].add(BigInteger.ONE);
1298	        }
1299	        boolean flipped = exact.stream().reduce(BigDecimal.ZERO, BigDecimal::add).signum() < 0;
1300	        List<BigDecimal> result = new ArrayList<>(n);
1301	        for (BigInteger share : shares) {
1302	            result.add(new BigDecimal(flipped ? share.negate() : share, scale()));
1303	        }
1304	        return result;
1305	    }
1306	
1307	    /** The sum of the exact line taxes, rounded once, half up to the cent. */
1308	    private BigDecimal roundTax(List<BigDecimal> exact) {
1309	        return exact.stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(scale(), RoundingMode.HALF_UP);
1310	    }
1311	
1312	    /**
1313	     * The tax charged at the given rate (a percentage): every line's exact tax added up and rounded
1314	     * once, half up to the cent. It is what the line taxes add up to.
1315	     */
1316	    public BigDecimal tax(BigDecimal taxRate) {
1317	        return roundTax(exactLineTaxes(taxRate));
1318	    }
1319	
1320	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
1321	    public BigDecimal total(BigDecimal taxRate) {
1322	        return subtotal().subtract(discount()).add(tax(taxRate));
1323	    }
